  "faq.title": "คำถามที่พบบ่อย",
  "faq.q1": "ไฟล์ของฉันถูกอัปโหลดหรือไม่",
  "faq.a1": "สำหรับเครื่องมือส่วนใหญ่ ไม่ เครื่องมือที่มีป้าย “ทำงานบนอุปกรณ์ของคุณ” จะไม่ส่งไฟล์ไปที่ใดเลย การแปลง Office และหน้าเว็บจะส่งไฟล์ไปยังเซิร์ฟเวอร์ของเรา ซึ่งจะประมวลผลแล้วลบทันที",
  "faq.a1Local": "ไม่ ทุกเครื่องมือทำงานในเบราว์เซอร์ของคุณ ไฟล์จึงไม่ออกจากอุปกรณ์ของคุณเลย",
  "faq.q2": "ใช้ฟรีไหม",
  "faq.a2": "ใช่ ทุกเครื่องมือใช้ได้ฟรี และไม่มีแผนแบบเสียเงิน",
  "faq.q3": "ต้องมีบัญชีไหม",
  "faq.a3": "ไม่ต้อง ทุกเครื่องมือใช้งานได้โดยไม่ต้องมีบัญชี และเวิร์กโฟลว์ที่คุณบันทึกจะอยู่ในเบราว์เซอร์ของคุณ",
  "faq.q4": "ทำไมไฟล์ที่บีบอัดแล้วไม่เล็กลง",
  "faq.a4": "การบีบอัดลดขนาดรูปภาพเป็นหลัก PDF ที่มีแต่ข้อความมีขนาดเล็กอยู่แล้ว เมื่อทำให้เล็กลงไม่ได้ เราจึงเก็บไฟล์ต้นฉบับไว้",
  "faq.q5": "ถ้าลืมรหัสผ่าน PDF คุณเปิดให้ได้ไหม",
  "faq.a5": "ไม่ได้ ปลดล็อก PDF ใช้ลบรหัสผ่านที่คุณรู้อยู่แล้ว เราไม่เจาะรหัสผ่าน",
  "faq.q6": "ทำไมหน้าดูต่างไปหลังการปกปิดข้อมูล",
  "faq.a6": "หน้าที่ปกปิดข้อมูลจะถูกสร้างใหม่เป็นรูปภาพเพื่อไม่ให้มีสิ่งใดหลงเหลือ ข้อความนอกพื้นที่ที่ปกปิดยังค้นหาได้",
  "faq.q7": "ใช้กับเบราว์เซอร์ใดได้บ้าง",
  "faq.a7": "Chrome, Edge, Firefox และ Safari เวอร์ชันปัจจุบัน ทั้งบนคอมพิวเตอร์และมือถือ",
  "faq.q8": "ไฟล์ใหญ่ได้แค่ไหน",
  "faq.a8": "เครื่องมือที่ทำงานบนอุปกรณ์ของคุณไม่จำกัดขนาดหรือจำนวนไฟล์ และไฟล์แรกก็ทำงานเหมือนไฟล์ที่ร้อย งานที่ใหญ่มากถูกจำกัดแค่หน่วยความจำของอุปกรณ์เท่านั้น",
  "sec.title": "ความปลอดภัย",
  "sec.subtitle": "เราจัดการไฟล์และข้อมูลของคุณอย่างไร",
  "sec.h1": "การประมวลผลบนอุปกรณ์ของคุณ",
  "sec.b1": "เครื่องมือส่วนใหญ่ทำงานเป็นโค้ดในแท็บเบราว์เซอร์ ไฟล์จะถูกอ่านจากดิสก์เข้าสู่หน่วยความจำ ประมวลผล แล้วส่งคืนให้คุณ ไม่ผ่านเครือข่ายเลย",
  "sec.h2": "การประมวลผลบนเซิร์ฟเวอร์",
  "sec.b2": "เครื่องมือ Office และหน้าเว็บต้องใช้เซิร์ฟเวอร์ ไฟล์จะถูกส่งผ่าน HTTPS ประมวลผลในหน่วยความจำหรือโฟลเดอร์ชั่วคราวส่วนตัว และลบทันทีเมื่อส่งผลลัพธ์แล้ว เราไม่เก็บสำเนา",
  "sec.h4": "รหัสผ่านของ PDF",
  "sec.b4": "รหัสผ่านที่คุณพิมพ์ในป้องกันหรือปลดล็อกจะอยู่ในเบราว์เซอร์เท่านั้นและไม่ถูกบันทึก รวมถึงในเวิร์กโฟลว์",
  "sec.checkTitle": "ตรวจสอบด้วยตัวเอง",
  "sec.check1": "ทุกหน้าสั่งให้เบราว์เซอร์ของคุณปฏิเสธการเชื่อมต่อไปยังเว็บไซต์อื่น ด้วย Content-Security-Policy ที่คุณอ่านได้ในส่วนหัวการตอบกลับของหน้า เบราว์เซอร์ของคุณเป็นผู้บังคับใช้ ไม่ใช่โค้ดของเรา",
  "sec.check2": "เปิดเครื่องมือสำหรับนักพัฒนาของเบราว์เซอร์ เลือก Network แล้วใช้เครื่องมือที่มีป้าย “ทำงานบนอุปกรณ์ของคุณ” จะไม่มีคำขอใดที่ส่งไฟล์ของคุณ และไม่มีคำขอใดไปยังเว็บไซต์อื่น",
  "sec.check3": "หรือเปิดเครื่องมือ ตัดการเชื่อมต่ออินเทอร์เน็ตหรือเปิดโหมดเครื่องบิน แล้วใช้งาน เครื่องมือที่ทำงานบนอุปกรณ์ใช้งานได้เหมือนเดิมโดยไม่ต้องเชื่อมต่อ",
  "sec.check4": "ป้ายในแต่ละหน้าเครื่องมือนับแบบสดถึงจำนวนไบต์ที่หน้าอัปโหลด คำขอไปยังเว็บไซต์อื่น และคำขอที่เบราว์เซอร์บล็อก ตัวเลขมาจากบันทึกการรับส่งข้อมูลของหน้าที่เบราว์เซอร์เก็บเอง",
