  "about.b1": "{brand} คือชุดเครื่องมือ PDF ที่สร้างจากแนวคิดเดียว: เอกสารของคุณเป็นของคุณ งานใดที่ทำบนอุปกรณ์ของคุณเองได้ ก็จะทำที่นั่น",
  "about.b2": "ครอบคลุมงานประจำวัน เช่น การรวม บีบอัด แปลง และลงนาม รวมถึงงานที่ต้องระมัดระวัง เช่น การปกปิดข้อมูล การจัดเก็บ และการเปรียบเทียบเวอร์ชัน",
  "about.b3": "มีคำถาม ไอเดีย หรือมีอะไรใช้งานไม่ได้? ติดต่อเรา หรือแจ้งปัญหาเพื่อให้แก้ไขได้",
