  "tool.split.q3": "ดึงหลายช่วงมาเป็น PDF ใหม่ไฟล์เดียวได้หรือไม่",
  "tool.split.a3": "ได้ เปิด “รวมทุกช่วงเป็น PDF เดียว” แล้วช่วงที่คุณระบุจะถูกบันทึกรวมกันเป็นไฟล์เดียว ตามลำดับที่คุณพิมพ์",
  "tool.split.q4": "ลิงก์และบุ๊กมาร์กยังอยู่หลังแยกหรือไม่",
  "tool.split.a4": "ลิงก์ที่ชี้ไปยังหน้าในส่วนเดียวกันยังใช้ได้ ลิงก์ไปยังหน้าที่ไปอยู่ในส่วนอื่นจะถูกลบ เพื่อไม่ให้ใครไปเจอหน้าที่ไม่มี",
  "tool.split.q5": "มีวิธีที่เร็วกว่าเพื่อเอาแค่ไม่กี่หน้าหรือไม่",
  "tool.split.a5": "ถ้าคุณอยากคลิกหน้ามากกว่าพิมพ์ตัวเลข “ดึงหน้า” จะแสดงภาพย่อของทั้งเอกสารและบันทึกหน้าที่คุณเลือก",
  "tool.split.private": "เอกสารถูกแยกด้วยโค้ดที่ทำงานในเบราว์เซอร์ของคุณ หน้าต่าง ๆ จึงไม่เคยถูกอัปโหลด การแยกสัญญา รายการเดินบัญชี หรือเวชระเบียน จึงเป็นส่วนตัวเท่ากับการเปิดบนคอมพิวเตอร์ของคุณเอง และไฟล์ที่แยกแล้วอยู่บนอุปกรณ์ของคุณจนกว่าคุณจะเลือกแชร์",
  "tool.extract.title": "ดึงหน้าจาก PDF ด้วยการคลิก",
  "tool.extract.meta": "คลิกหน้าที่ต้องการแล้วบันทึกเป็น PDF ใหม่ หรือแยกหนึ่งไฟล์ต่อหน้า ภาพย่อช่วยให้ทำได้ง่าย และ PDF ไม่เคยออกจากอุปกรณ์ของคุณ ฟรี ไม่ต้องสมัคร",
  "tool.extract.intro": "ดึงหน้าจะสร้าง PDF ใหม่จากเฉพาะหน้าที่คุณเลือก โดยไม่แตะไฟล์ต้นฉบับ ทุกหน้าแสดงเป็นภาพย่อ คุณจึงหาหน้าลายเซ็น ใบเสร็จ หรือแผนภูมิที่ต้องการได้โดยไม่ต้องนับ หน้าต่าง ๆ ถูกคัดลอกตามเดิม คงข้อความ รูปภาพ และลิงก์ไปยังหน้าอื่นที่คุณดึงออกมาด้วย",
  "tool.extract.step1": "เปิด PDF ภาพย่อของทุกหน้าจะปรากฏเป็นตาราง",
