  "tool.extract.q2": "หน้าถูกบันทึกตามลำดับใด",
  "tool.extract.a2": "ตามลำดับเดิม ถ้าต้องการจัดเรียงใหม่ด้วย ให้เปิดผลลัพธ์ใน “จัดระเบียบ PDF” แล้วลากหน้าไปตำแหน่งที่ต้องการ",
  "tool.extract.q3": "ต่างจาก “แยก PDF” อย่างไร",
