  "tool.extract.q4": "ดึงหน้าจาก PDF ที่สแกนได้หรือไม่",
  "tool.extract.a4": "ได้ หน้าที่สแกนคือรูปภาพใน PDF และถูกคัดลอกเหมือนหน้าอื่น ถ้าต้องการค้นหาข้อความด้วย ให้ใช้ “OCR สำหรับ PDF” กับผลลัพธ์",
  "tool.extract.q5": "ดึงหน้าจาก PDF หลายไฟล์ได้หรือไม่",
  "tool.extract.a5": "ดึงหน้าทำงานกับไฟล์ทีละไฟล์ ถ้าต้องการรวบรวมหน้าจาก PDF หลายไฟล์เป็นเอกสารเดียว ให้ใช้ “จัดระเบียบ PDF” ซึ่งโหลดไฟล์เหล่านั้นไว้ข้างกัน",
  "tool.extract.private": "ภาพย่อถูกวาดและไฟล์ใหม่ถูกสร้างในเบราว์เซอร์ของคุณ {brand} ไม่มีขั้นตอนบนเซิร์ฟเวอร์สำหรับเครื่องมือนี้ หน้าที่คุณดูและหน้าที่คุณเก็บจึงไม่เคยถูกส่ง บันทึก หรือเก็บไว้ที่ใดนอกจากอุปกรณ์ของคุณ",
  "tool.remove.title": "ลบหน้าออกจาก PDF ออนไลน์ ไม่ต้องอัปโหลด",
  "tool.remove.meta": "ลบหน้าว่าง หน้าซ้ำ หรือหน้าที่ไม่ต้องการออกจาก PDF โดยคลิกภาพย่อ ไฟล์ที่ทำความสะอาดแล้วบันทึกในเบราว์เซอร์ ไม่เคยถูกอัปโหลด ฟรี",
  "tool.remove.intro": "ลบหน้าจะลบหน้าที่คุณไม่ต้องการอีกแล้ว เช่น แผ่นเปล่าจากการสแกนสองหน้า หน้าปก ภาคผนวกที่ล้าสมัย หรือหน้าที่มีรายละเอียดที่ไม่ควรส่งต่อ ส่วนอื่นทั้งหมดคงไว้ตามเดิมทุกประการ หน้าที่เหลือเรียงตามลำดับเดิมและคงคุณภาพเดิม",
  "tool.remove.step1": "เปิด PDF ที่ต้องการทำความสะอาด แต่ละหน้าจะแสดงเป็นภาพย่อ",
  "tool.remove.step2": "คลิกทุกหน้าที่ต้องการลบ หน้าที่คลิกจะถูกทำเครื่องหมาย และคลิกอีกครั้งเพื่อนำกลับมา",
  "tool.remove.step3": "กด “ลบหน้า” แล้วดาวน์โหลด PDF ที่สั้นลง ไฟล์ต้นฉบับของคุณไม่เปลี่ยน",
  "tool.remove.q1": "เนื้อหาของหน้าที่ลบหายไปจริงหรือไม่",
