  "tool.remove.q2": "ลบหน้าจาก PDF หลายไฟล์พร้อมกันได้หรือไม่",
  "tool.remove.a2": "ลบหน้าทำงานกับไฟล์ทีละไฟล์ “จัดระเบียบ PDF” โหลดหลายไฟล์พร้อมกันได้ ให้คุณลบหน้าจากแต่ละไฟล์แล้วบันทึกเป็นเอกสารเดียว",
  "tool.remove.q3": "ถ้าลบหน้าผิดล่ะ",
  "tool.remove.a3": "คลิกหน้านั้นอีกครั้งก่อนบันทึกเพื่อเก็บไว้ หลังบันทึกแล้ว ไฟล์ต้นฉบับยังอยู่บนดิสก์ คุณจึงเริ่มใหม่ได้เลย",
  "tool.remove.q4": "เลขหน้าที่พิมพ์บนหน้าจะอัปเดตหรือไม่",
