  "tool.pageNumbers.q2": "“สลับด้านสำหรับหน้าคู่” ทำอะไร",
  "tool.pageNumbers.a2": "สำหรับเอกสารที่พิมพ์สองหน้า เลขบนหน้าซ้ายจะย้ายไปอีกด้าน เลขจึงอยู่ขอบด้านนอกของหน้าคู่เสมอ",
