  "tool.pageNumbers.q4": "ใส่เลขหน้าใน PDF หลายไฟล์พร้อมกันได้หรือไม่",
  "tool.pageNumbers.a4": "ได้ เพิ่มหลายไฟล์แล้วแต่ละไฟล์จะถูกใส่เลขแยกกันด้วยการตั้งค่าเดียวกัน ถ้าต้องการเลขต่อเนื่องเป็นเอกสารเดียว ให้รวมไฟล์ก่อน",
  "tool.pageNumbers.q5": "เปลี่ยนขนาดและสีของเลขได้หรือไม่",
  "tool.pageNumbers.a5": "ได้ ตั้งขนาดตัวอักษรและเลือกสีใดก็ได้ ให้เลขโดดเด่นหรือกลมกลืนกับดีไซน์ของหน้า",
  "tool.pageNumbers.private": "เลขถูกวาดลงบนหน้าด้วยโค้ดในเบราว์เซอร์ของคุณ และ PDF ที่มีเลขหน้าถูกบันทึกลงอุปกรณ์ของคุณโดยตรง เอกสารไม่ถูกอัปโหลด ต้นฉบับหนังสือและรายงานจึงเป็นของคุณ",
  "tool.watermark.title": "ใส่ลายน้ำแบบข้อความหรือรูปภาพใน PDF",
  "tool.watermark.meta": "ประทับข้อความอย่าง CONFIDENTIAL หรือโลโก้ของคุณบนหน้า PDF ปรับขนาด สี ความทึบ มุม ตำแหน่ง และการทำซ้ำได้ ไม่ต้องอัปโหลดไฟล์ ฟรี",
  "tool.watermark.intro": "ใส่ลายน้ำประทับข้อความหรือรูปภาพบนหน้าของ PDF เช่น ป้าย “ฉบับร่าง” หรือ “ลับ” โลโก้บริษัท หรือหมายเหตุว่าส่งสำเนาให้ใคร ปรับขนาด สี ความทึบ และมุม วางไว้ในตำแหน่งใดก็ได้จากเก้าตำแหน่ง หรือทำซ้ำทั่วทั้งหน้า และเลือกว่าจะให้อยู่เหนือหรือใต้เนื้อหา",
  "tool.watermark.step1": "เพิ่ม PDF หนึ่งไฟล์ขึ้นไปที่จะใส่ลายน้ำ",
  "tool.watermark.step2": "เลือกข้อความหรือรูปภาพ แล้วตั้งขนาด สี ความทึบ มุม และตำแหน่ง เปิด “ทำซ้ำทั่วทั้งหน้า” เพื่อได้ลวดลายซ้ำ และเลือกหน้าที่จะประทับ",
  "tool.watermark.step3": "กด “ใส่ลายน้ำ” แล้วดาวน์โหลด PDF ที่ประทับแล้ว",
