  "tool.watermark.a1": "เหนือเนื้อหาจะวาดทับด้านบนและมองข้ามได้ยาก ใต้เนื้อหาอยู่หลังข้อความและรูปภาพ จึงเห็นเฉพาะในพื้นที่ว่าง และหน้ายังอ่านง่าย",
  "tool.watermark.q2": "ลายน้ำถูกลบได้หรือไม่",
  "tool.watermark.a2": "ลายน้ำถูกเพิ่มเข้าไปในเนื้อหาของหน้า จึงยังอยู่เมื่อพิมพ์และคัดลอก แต่คนที่ตั้งใจและมีโปรแกรมแก้ไข PDF ลบได้ ลายน้ำเป็นเครื่องยับยั้ง ไม่ใช่การป้องกัน สำหรับการป้องกันให้ใช้ “ป้องกัน PDF”",
