  "wf.linkInBar": "ลิงก์สูตรอยู่ในแถบที่อยู่แล้ว คัดลอกจากตรงนั้นได้เลย ไฟล์และรหัสผ่านของคุณไม่ถูกรวมไว้ในลิงก์เลย",
